BEGIN;

INSERT INTO public.modulos (ordem, titulo, emoji, cor, categoria_id, descricao)
SELECT 24, 'Brasil República (1889 até hoje)', '🇧🇷', '#059669', 1, 'Depois do Império: da Proclamação de 1889 às oligarquias, a Era Vargas, a ditadura militar, a Constituição de 1988 e os desafios do Brasil contemporâneo.'
