INSERT INTO public.licoes (submodulo_id, ordem, titulo, emoji, conteudo)
SELECT s.id, 1, s.titulo, '🇧🇷',
       jsonb_build_object('preview', v.preview)
FROM _seed_trail t
JOIN public.submodulos s ON s.modulo_id = t.modulo_id
JOIN (VALUES
  (1, 'Em 15 de novembro de 1889, um movimento liderado por militares, com apoio de republicanos civis, depôs a monarquia; a participação popular direta foi pequena. Deodoro da Fonseca chefiou o Governo Provisório e foi o primeiro presidente. A Constituição de 1891 criou uma república federativa e presidencialista, mas o voto era aberto e excluía analfabetos e, na prática, mulheres. Os primeiros anos, da ''República da Espada'', deram lugar aos presidentes civis a partir de 1894.'),
  (2, 'A Primeira República combinou eleições regulares com fraude e dependência local. No interior, o coronelismo — conceito difundido por Victor Nunes Leal — trocava votos por favores e proteção entre chefes locais, governadores e presidente. A política dos governadores, de Campos Sales, consolidou esse pacto. Presidentes de São Paulo (café) e Minas Gerais (leite) predominaram, embora a alternância nunca tenha sido perfeita.'),
  (3, 'A jovem República enfrentou conflitos sociais. Canudos (Bahia, 1896–1897) foi uma comunidade sertaneja liderada por Antônio Conselheiro, destruída após quatro expedições militares; Euclides da Cunha a retratou em Os Sertões. Em 1904, no Rio de Janeiro, a reforma urbana de Pereira Passos e a vacinação obrigatória contra a varíola, conduzida por Oswaldo Cruz, provocaram a Revolta da Vacina: protesto popular, repressão e estado de sítio.'),
  (4, 'A sucessão de 1930 rompeu o arranjo paulista-mineiro: o presidente Washington Luís apoiou outro paulista, Júlio Prestes, que venceu a eleição. Minas, Rio Grande do Sul e Paraíba apoiaram Getúlio Vargas na Aliança Liberal; o assassinato de João Pessoa serviu de estopim para a Revolução de 1930. No Governo Provisório, foi criado o Ministério do Trabalho e o Código Eleitoral de 1932 trouxe voto secreto, Justiça Eleitoral e voto feminino. São Paulo se levantou na Revolução Constitucionalista de 1932.'),
  (5, 'Em 10 de novembro de 1937, Vargas fechou o Congresso e outorgou uma Constituição autoritária, usando como pretexto o Plano Cohen, um documento forjado. O Estado Novo (1937–1945) teve censura, propaganda do DIP e repressão política. Ao mesmo tempo, consolidou direitos trabalhistas controlados pelo Estado: salário mínimo (1940), imposto sindical e a CLT (1943). A siderurgia de Volta Redonda marcou o projeto industrializante.'),
  (6, 'A deposição de Vargas em 1945 abriu a república de 1946, com eleições, partidos nacionais (PSD, UDN, PTB) e nova Constituição. Vargas voltou eleito em 1950 e se suicidou em agosto de 1954. JK prometeu ''50 anos em 5'' e inaugurou Brasília em 1960. A renúncia de Jânio Quadros (1961) levou a um parlamentarismo improvisado para dar posse a João Goulart; o plebiscito de 1963 restaurou o presidencialismo, em meio a polarização da Guerra Fria.'),
  (7, 'Em 31 de março e 1º de abril de 1964, militares depuseram João Goulart com apoio de setores civis, empresariais e da imprensa. O Congresso declarou a Presidência vaga e elegeu o marechal Castelo Branco. O AI-1 cassou mandatos; o AI-2 extinguiu os partidos e criou o bipartidarismo (ARENA e MDB). Em 1968, o AI-5 ampliou os poderes do Executivo. O regime durou até 1985, com presidentes militares escolhidos indiretamente.'),
  (8, 'Após o AI-5 (dezembro de 1968), o Congresso ficou fechado por cerca de dez meses, houve cassações, censura prévia e tortura em órgãos como o DOI-CODI. Parte da oposição escolheu a luta armada; outros resistiram na imprensa, na música, na Igreja, no movimento estudantil e nos sindicatos. Entre 1968 e 1973, o ''milagre econômico'' trouxe crescimento alto do PIB, mas com arrocho salarial, concentração de renda e dívida externa. A Comissão Nacional da Verdade (relatório de 2014) documentou mortes e desaparecimentos.'),
  (9, 'No governo Geisel (1974–1979), o regime anunciou uma distensão ''lenta, gradual e segura'', controlada pelos militares. A morte de Vladimir Herzog sob custódia em 1975, a crise econômica, as greves do ABC e a campanha pela anistia aumentaram a pressão. O AI-5 foi extinto no início de 1979 e a Lei de Anistia (28 de agosto de 1979, governo Figueiredo) permitiu o retorno de exilados; foi também interpretada como alcançando agentes do Estado, tema ainda debatido. A reforma partidária encerrou o bipartidarismo.'),
  (10, 'A crise econômica e o desgaste do regime alimentaram as Diretas Já (1983–1984). A emenda Dante de Oliveira foi rejeitada na Câmara em abril de 1984, mas Tancredo Neves foi eleito pelo Colégio Eleitoral em janeiro de 1985; doente, morreu antes da posse e José Sarney assumiu. A Assembleia Constituinte (1987–1988), presidida por Ulysses Guimarães, promulgou em 5 de outubro de 1988 a ''Constituição Cidadã'', com direitos sociais, SUS e racismo como crime inafiançável e imprescritível.'),
  (11, 'Nas décadas de 1980 e 1990, a inflação crônica corroía salários e vários planos falharam (Cruzado, Collor). Em 1989, houve a primeira eleição direta para presidente desde 1960; em 1992, Collor sofreu processo de impeachment e Itamar Franco assumiu. Com Fernando Henrique Cardoso na Fazenda, a URV preparou a nova moeda: o Real entrou em circulação em 1º de julho de 1994. A inflação caiu fortemente e FHC se elegeu no primeiro turno em 1994, mas a estabilização dependeu de juros altos e de ajustes posteriores.'),
  (12, 'Desde 2002, o Brasil teve transições por eleição e uma por impeachment: Lula (2003–2010), Dilma Rousseff, primeira mulher eleita presidente (2011–2016, afastada por processo aprovado no Congresso), Michel Temer, Jair Bolsonaro (2019–2022) e Lula novamente a partir de 2023. A reeleição existe desde 1997 e a urna eletrônica é usada em todo o país desde 2000. Entre as disputas permanentes estão desigualdade, papel do Estado, polarização e o equilíbrio entre Executivo, Congresso e Judiciário.')
) AS v(sub_ordem, preview) ON v.sub_ordem = s.ordem
WHERE NOT EXISTS (SELECT 1 FROM public.licoes l WHERE l.submodulo_id = s.id);

